def dividir(a: float, b: float) -> float:
    if b == 0:
        raise ValueError("Divisor não pode ser zero")
    return a / b

try:
    resultado = dividir(10, 0)
except ValueError as erro:
    print("Erro capturado:", erro)
finally:
    print("Operação finalizada")

